@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800&family=Inter:wght@500;600;700&display=swap');
:root{--ink:#17212b;--navy:#202d3a;--cream:#edf0ed;--gold:#e6ad32;--green:#39b87d;--blue:#4b87b9}
*{box-sizing:border-box}body{margin:0;font-family:Inter,sans-serif;background:#dfe4df;color:var(--ink);height:100vh;overflow:hidden}.topbar{height:86px;background:#1d2934;color:white;display:flex;align-items:center;padding:0 28px;border-bottom:4px solid #e3ad3a}.brand{display:flex;align-items:center;width:245px;font-family:'Barlow Condensed';font-size:21px;line-height:.85}.brand span{display:block;color:#abb5bd;font-size:14px;letter-spacing:5px;margin-top:7px}.brand-mark{width:44px;height:44px;border:2px solid #e3ad3a;color:#e3ad3a;display:grid;place-items:center;font-size:20px;margin-right:12px;transform:skew(-5deg)}.stats{display:flex;gap:38px;height:48px}.stat{display:flex;align-items:center;gap:10px;border-right:1px solid #3a4650;padding-right:38px}.stat:last-child{border:0}.stat-icon{width:34px;height:34px;border-radius:50%;background:#3d5152;display:grid;place-items:center;color:#69ce9e;font:bold 18px Georgia}.stat-icon.gold{background:#4d472f;color:#f2bd4d}.stat-icon.blue{background:#354a5a;color:#70b6df}.stat small,.income small{display:block;color:#97a4ae;font-size:9px;letter-spacing:1.5px;margin-bottom:4px}.stat strong{font-family:'Barlow Condensed';font-size:20px}.next-day{margin-left:auto;background:#e5aa32;border:0;color:#1e2a31;height:48px;padding:0 18px;font:800 14px 'Barlow Condensed';letter-spacing:1px;cursor:pointer}.next-day span{font-size:25px;vertical-align:-2px;margin-left:12px}
main{display:flex;height:calc(100vh - 86px)}.sidebar{width:245px;background:#26333e;color:#dbe2e5;padding:22px 18px 16px;display:flex;flex-direction:column}.profile{height:62px;border-bottom:1px solid #3b4852;display:flex;gap:10px}.avatar{width:42px;height:42px;border-radius:50%;background:linear-gradient(135deg,#d09b6b,#6b4938);border:3px solid #dbe2e5;display:grid;place-items:center;font-weight:bold}.profile small{display:block;color:#91a0a9;font-size:9px;margin:6px 0 3px}.profile strong{font:700 15px 'Barlow Condensed'}nav{margin-top:18px}.nav{width:100%;height:48px;border:0;border-left:3px solid transparent;background:none;color:#adb8bf;text-align:left;padding:0 12px;font:700 13px 'Barlow Condensed';letter-spacing:1.2px;cursor:pointer}.nav i{font-style:normal;display:inline-block;width:28px;color:#7f929d;font-size:18px}.nav b{float:right;background:#465763;border-radius:10px;padding:2px 7px;font-size:10px}.nav.active{background:#1f2b35;border-left-color:#e5aa32;color:white}.nav.active i{color:#e5aa32}.side-bottom{margin-top:auto;display:flex;gap:8px}.small-btn{height:38px;border:1px solid #465560;background:#303f49;color:#c0cad0;font:700 11px 'Barlow Condensed';cursor:pointer}.small-btn:first-child{flex:1}.small-btn:last-child{width:38px}
.content{flex:1;padding:24px 30px 18px;overflow:hidden}.view-head{height:68px;display:flex;justify-content:space-between;border-bottom:1px solid #ccd3ce}.view-head p{margin:0 0 3px;color:#9a9e98;font-size:9px;letter-spacing:2px}.view-head h1{margin:0;font:800 29px 'Barlow Condensed';letter-spacing:.2px}.income{text-align:right;padding-top:8px}.income strong{color:#2d9a68;font:800 22px 'Barlow Condensed'}.view{display:none}.view.active{display:block}.city-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:16px}.property{height:154px;background:#f7f8f6;border:1px solid #d2d7d2;position:relative;overflow:hidden;cursor:pointer;transition:.15s}.property:hover{transform:translateY(-2px);box-shadow:0 6px 16px #aeb7ae55}.property.locked{filter:saturate(.3);cursor:pointer}.building-art{height:105px;position:relative;background:linear-gradient(#dce9ed 0 70%,#bdc8bb 70%)}.building-art:after{content:'';position:absolute;bottom:0;left:0;right:0;height:18px;background:repeating-linear-gradient(90deg,#8b9c82 0 24px,#b2bdaa 24px 26px)}.building{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);background:#788b91;border:7px solid #dfe5e3;border-bottom:0}.building.cafe{width:58px;height:48px;background:#c58b57}.building.cafe:before{content:'';position:absolute;left:-8px;top:-22px;width:62px;height:18px;background:#4d6d75}.building.office{width:72px;height:73px;background:#728895}.office:before{content:'';position:absolute;inset:8px 8px 12px;background:repeating-linear-gradient(90deg,#b9ced2 0 8px,transparent 8px 13px)}.building.store{width:82px;height:53px;background:#9a7d55}.store:before{content:'';position:absolute;left:8px;top:-14px;width:66px;height:18px;background:repeating-linear-gradient(135deg,#e7e3c8 0 8px,#b94e42 8px 16px)}.building.hotel{width:65px;height:82px;background:#8e9e94}.hotel:before{content:'★';position:absolute;top:-21px;width:100%;text-align:center;color:#cfae55;font-size:18px}.building.construction{width:70px;height:48px;border:0;background:repeating-linear-gradient(45deg,#e0ad3a 0 8px,#343e43 8px 16px)}.property-info{height:49px;padding:8px 10px;display:flex;justify-content:space-between}.property-info h3{margin:0;font:800 15px 'Barlow Condensed'}.property-info p{margin:3px 0 0;color:#879087;font-size:9px}.property-info strong{color:#34845c;font:800 14px 'Barlow Condensed';align-self:center}.level{position:absolute;right:7px;top:7px;background:#26343e;color:white;font:700 9px 'Barlow Condensed';padding:4px 6px}.lock{position:absolute;inset:0;background:#26333e88;color:white;display:grid;place-items:center;text-align:center;font:800 16px 'Barlow Condensed'}.news{height:48px;background:#26333e;color:#dce4e5;margin-top:14px;display:flex;align-items:center;font-size:11px}.news-label{align-self:stretch;width:108px;background:#e5aa32;color:#26333e;display:grid;place-items:center;font:800 11px 'Barlow Condensed';letter-spacing:1px;margin-right:14px}
.business-list,.market-list,.mission-list{margin-top:16px;display:grid;gap:10px}.biz-row,.market-row,.mission-row{height:82px;background:#f7f8f6;border:1px solid #d2d7d2;display:flex;align-items:center;padding:10px 14px}.biz-icon,.market-icon{width:62px;height:62px;background:#8a9b9e;display:grid;place-items:center;font-size:25px;margin-right:14px}.biz-info{flex:1}.biz-info h3,.market-info h3,.mission-info h3{margin:0;font:800 17px 'Barlow Condensed'}.biz-info p,.market-info p,.mission-info p{margin:4px 0;color:#879087;font-size:10px}.biz-actions{display:flex;align-items:center;gap:8px}.buy-btn,.upgrade-btn{border:0;background:#26333e;color:white;height:38px;padding:0 13px;font:800 12px 'Barlow Condensed';cursor:pointer}.upgrade-btn{background:#dfaa38;color:#26333e}.market-row{height:75px}.market-icon{height:55px;width:55px;background:#dce3df}.mission-row{height:74px}.mission-check{width:38px;height:38px;border:2px solid #b9c2ba;border-radius:50%;margin-right:12px;display:grid;place-items:center}.mission-row.done .mission-check{background:#43a978;border-color:#43a978;color:white}.mission-info{flex:1}.reward{color:#34845c;font:800 16px 'Barlow Condensed'}
.modal{position:fixed;inset:0;background:#18232a99;display:grid;place-items:center}.hidden{display:none}.modal-card{width:min(420px,90vw);background:#f6f7f4;padding:24px;position:relative;box-shadow:0 20px 60px #10191e55}.close{position:absolute;right:10px;top:8px;border:0;background:none;font-size:22px;cursor:pointer}.modal-card h2{font:800 26px 'Barlow Condensed';margin:0}.modal-card p{font-size:12px;color:#738078}.modal-card .upgrade-btn{margin-top:12px}.toast{position:fixed;left:50%;bottom:25px;transform:translate(-50%,20px);background:#26333e;color:white;padding:10px 18px;font-size:12px;opacity:0;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:800px){.sidebar{width:72px;padding:22px 8px}.brand{width:180px}.brand div:last-child{display:none}.profile div:last-child,nav .nav:not(.active){font-size:0}.profile{justify-content:center}.nav{font-size:0;text-align:center}.nav i{font-size:20px}.nav b{display:none}.side-bottom{display:none}.stats{gap:10px}.stat{padding-right:10px}.stat:nth-child(2){display:none}.content{padding:20px 16px}.city-grid{grid-template-columns:repeat(2,1fr)}.property:nth-child(n+5){display:none}.next-day{padding:0 10px}.next-day span{display:none}}

const types=[
 {name:'Corner Cafe',type:'cafe',level:2,base:480,cost:6000,icon:'☕'},
 {name:'Metro Offices',type:'office',level:3,base:820,cost:9500,icon:'▥'},
 {name:'Grand Mart',type:'store',level:1,base:650,cost:7500,icon:'▤'},
 {name:'Downtown Hotel',type:'hotel',level:0,base:1200,cost:18000,icon:'♜'},
 {name:'Creative Labs',type:'office',level:0,base:900,cost:14000,icon:'▦'},
 {name:'Riverside Plaza',type:'construction',level:0,base:1600,cost:26000,icon:'🏗'}
];
let state={cash:12500,rep:120,day:1,owned:[0,1,2],properties:types.map(p=>({...p}))};
try{const s=JSON.parse(localStorage.getItem('businessTycoonSave'));if(s&&s.properties)state=s}catch(e){}
const $=s=>document.querySelector(s), money=n=>'$'+Math.round(n).toLocaleString();
function income(){return state.properties.reduce((sum,p,i)=>state.owned.includes(i)?sum+p.base*(1+p.level*.32):sum,0)}
function render(){
 $('#cash').textContent=money(state.cash);$('#rep').textContent=state.rep;$('#day').textContent=state.day;
 $('#income').textContent='+$'+Math.round(income()).toLocaleString();$('#ownedCount').textContent=state.owned.length;
 const grid=$('#cityGrid');grid.innerHTML='';
 state.properties.forEach((p,i)=>{const owned=state.owned.includes(i);const el=document.createElement('div');el.className='property'+(owned?'':' locked');el.innerHTML=`<div class="building-art"><div class="building ${p.type}"></div></div><div class="level">${owned?'LV '+p.level:'LOT '+(i+1)}</div>${owned?'':`<div class="lock">AVAILABLE<br><span>$${p.cost.toLocaleString()}</span></div>`}<div class="property-info"><div><h3>${p.name}</h3><p>${owned?'PRODUCING':'COMMERCIAL LOT'}</p></div>${owned?`<strong>+$${Math.round(p.base*(1+p.level*.32)).toLocaleString()}</strong>`:''}</div>`;el.onclick=()=>openProperty(i);grid.appendChild(el)});
 renderBusinesses();renderMarket();renderMissions();
}
function openProperty(i){const p=state.properties[i],owned=state.owned.includes(i);let html=`<h2>${p.name}</h2><p>${owned?'Daily earnings: '+money(p.base*(1+p.level*.32)):'Acquire this property to expand your commercial empire.'}</p>`;if(owned)html+=`<p>LEVEL ${p.level} · UPGRADE COST ${money(p.cost*.65*(p.level+1))}</p><button class="upgrade-btn" id="modalAction">UPGRADE PROPERTY</button>`;else html+=`<p>Purchase cost: ${money(p.cost)}</p><button class="upgrade-btn" id="modalAction">BUY PROPERTY</button>`;$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden');$('#modalAction').onclick=()=>{if(owned)upgrade(i);else buy(i);$('#modal').classList.add('hidden')};}
function buy(i){const p=state.properties[i];if(state.cash<p.cost)return toast('Not enough cash');state.cash-=p.cost;state.owned.push(i);state.rep+=15;toast(p.name+' acquired!');render()}
function upgrade(i){const p=state.properties[i],cost=p.cost*.65*(p.level+1);if(state.cash<cost)return toast('Not enough cash');state.cash-=cost;p.level++;state.rep+=8;toast(p.name+' upgraded to level '+p.level);render()}
function renderBusinesses(){const el=$('#businessList');el.innerHTML='';state.owned.forEach(i=>{const p=state.properties[i];const row=document.createElement('div');row.className='biz-row';row.innerHTML=`<div class="biz-icon">${p.icon}</div><div class="biz-info"><h3>${p.name}</h3><p>LEVEL ${p.level} · DAILY PROFIT ${money(p.base*(1+p.level*.32))}</p></div><div class="biz-actions"><button class="upgrade-btn">UPGRADE · ${money(p.cost*.65*(p.level+1))}</button></div>`;row.querySelector('button').onclick=()=>upgrade(i);el.appendChild(row)})}
const market=[{name:'Local Supply Co.',desc:'Boost retail income by 10% for 5 days',cost:2400,icon:'▥'},{name:'Marketing Agency',desc:'Gain 25 reputation immediately',cost:1800,icon:'◉'},{name:'City Consultant',desc:'Instant +$8,000 consulting bonus',cost:5200,icon:'◆'}];
function renderMarket(){const el=$('#marketList');el.innerHTML='';market.forEach((m,i)=>{const r=document.createElement('div');r.className='market-row';r.innerHTML=`<div class="market-icon">${m.icon}</div><div class="market-info"><h3>${m.name}</h3><p>${m.desc}</p></div><button class="buy-btn">BUY · ${money(m.cost)}</button>`;r.querySelector('button').onclick=()=>{if(state.cash<m.cost)return toast('Not enough cash');state.cash-=m.cost;if(i===0){state.properties.forEach(p=>p.base*=1.1)}if(i===1)state.rep+=25;if(i===2)state.cash+=8000;toast('Investment activated');render()};el.appendChild(r)})}
const missions=[{name:'First Expansion',desc:'Own 4 properties',reward:1500,check:()=>state.owned.length>=4},{name:'Local Legend',desc:'Reach 150 reputation',reward:2000,check:()=>state.rep>=150},{name:'Daily Profit',desc:'Earn $3,500 per day',reward:2500,check:()=>income()>=3500}];
let claimed=[];try{claimed=JSON.parse(localStorage.getItem('businessTycoonClaimed'))||[]}catch(e){}
function renderMissions(){const el=$('#missionList');el.innerHTML='';missions.forEach((m,i)=>{const complete=m.check(),done=claimed.includes(i);const r=document.createElement('div');r.className='mission-row'+(done?' done':'');r.innerHTML=`<div class="mission-check">${done?'✓':''}</div><div class="mission-info"><h3>${m.name}</h3><p>${m.desc}</p></div><div class="reward">${done?'CLAIMED':'+ '+money(m.reward)}</div>`;if(complete&&!done)r.onclick=()=>{claimed.push(i);state.cash+=m.reward;localStorage.setItem('businessTycoonClaimed',JSON.stringify(claimed));toast('Mission reward claimed: '+money(m.reward));render()};el.appendChild(r)});$('#missionCount').textContent=missions.filter((m,i)=>m.check()&&!claimed.includes(i)).length}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(el.timer);el.timer=setTimeout(()=>el.classList.remove('show'),1800)}
$('#nextDay').onclick=()=>{const earned=income();state.cash+=earned;state.day++;const news=['Street traffic is at a record high!','Investors are watching the downtown district.','A new competitor opened across town.','Commercial rents have increased this quarter.'];$('#newsText').textContent=news[(state.day-2)%news.length];toast('Day '+state.day+' · '+money(earned)+' collected');save(false);render()};
function save(show=true){localStorage.setItem('businessTycoonSave',JSON.stringify(state));if(show)toast('Game saved')}
$('#saveBtn').onclick=()=>save(true);$('#settingsBtn').onclick=()=>{openProperty(state.owned[0])};
$('#closeModal').onclick=()=>$('#modal').classList.add('hidden');$('#modal').onclick=e=>{if(e.target.id==='modal')e.classList.add('hidden')};
document.querySelectorAll('.nav').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.nav').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));const map={city:'cityView',businesses:'businessView',market:'marketView',missions:'missionsView'};$('#'+map[btn.dataset.view]).classList.add('active');const titles={city:'Downtown District',businesses:'My Businesses',market:'Investment Market',missions:'Tycoon Missions'};$('#viewTitle').textContent=titles[btn.dataset.view];$('#viewTitle').nextElementSibling&&($('#viewTitle').nextElementSibling.style.display='')});
render();

